PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS import_jobs;DROP TABLE IF EXISTS audit_events;DROP TABLE IF EXISTS quarantine_items;DROP TABLE IF EXISTS aliases;DROP TABLE IF EXISTS rules;DROP TABLE IF EXISTS contacts;DROP TABLE IF EXISTS attachments;DROP TABLE IF EXISTS deliveries;DROP TABLE IF EXISTS messages;DROP TABLE IF EXISTS folders;DROP TABLE IF EXISTS settings;DROP TABLE IF EXISTS sessions;DROP TABLE IF EXISTS reset_tokens;DROP TABLE IF EXISTS mailboxes;DROP TABLE IF EXISTS domain_admins;DROP TABLE IF EXISTS domains;DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('mailbox_user','domain_admin','platform_admin')),status TEXT NOT NULL);
CREATE TABLE domains(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,status TEXT NOT NULL);
CREATE TABLE domain_admins(user_id INTEGER NOT NULL REFERENCES users(id),domain_id INTEGER NOT NULL REFERENCES domains(id),PRIMARY KEY(user_id,domain_id));
CREATE TABLE mailboxes(id INTEGER PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id),domain_id INTEGER NOT NULL REFERENCES domains(id),address TEXT UNIQUE NOT NULL,quota_mb INTEGER NOT NULL,used_mb INTEGER NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE reset_tokens(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE folders(id INTEGER PRIMARY KEY,mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id),name TEXT NOT NULL,UNIQUE(mailbox_id,name));
CREATE TABLE messages(id INTEGER PRIMARY KEY,mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id),folder_id INTEGER NOT NULL REFERENCES folders(id),sender TEXT NOT NULL,recipients TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,is_read INTEGER NOT NULL,is_flagged INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,idempotency_key TEXT,UNIQUE(mailbox_id,idempotency_key));
CREATE TABLE deliveries(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id),status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE attachments(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,filename TEXT NOT NULL,mime TEXT NOT NULL,content TEXT NOT NULL,size INTEGER NOT NULL,UNIQUE(message_id,filename));
CREATE TABLE contacts(id INTEGER PRIMARY KEY,mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id),name TEXT NOT NULL,email TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(mailbox_id,email));
CREATE TABLE rules(id INTEGER PRIMARY KEY,mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id),name TEXT NOT NULL,condition_field TEXT NOT NULL,condition_value TEXT NOT NULL,action_type TEXT NOT NULL,action_value TEXT NOT NULL,position INTEGER NOT NULL,enabled INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(mailbox_id,name),UNIQUE(mailbox_id,position));
CREATE TABLE aliases(id INTEGER PRIMARY KEY,domain_id INTEGER NOT NULL REFERENCES domains(id),source TEXT NOT NULL,destination TEXT NOT NULL,UNIQUE(domain_id,source));
CREATE TABLE quarantine_items(id INTEGER PRIMARY KEY,domain_id INTEGER NOT NULL REFERENCES domains(id),recipient TEXT NOT NULL,sender TEXT NOT NULL,subject TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),domain_id INTEGER REFERENCES domains(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE import_jobs(id INTEGER PRIMARY KEY,mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id),imported INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE settings(mailbox_id INTEGER PRIMARY KEY REFERENCES mailboxes(id),signature TEXT NOT NULL,vacation_enabled INTEGER NOT NULL,vacation_message TEXT NOT NULL,forwarding_enabled INTEGER NOT NULL,forwarding_address TEXT NOT NULL,display_density TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
